const data = $input.first().json;
if (data.schema_version !== 1 || !Array.isArray(data.reports) || data.official_test_evaluated !== false) throw new Error('Unexpected evaluation schema or official test status');
const lines = ['# Meal Discovery AI — relatório automatizado', '', 'Fonte: API local de avaliações versionadas. Teste oficial não avaliado.', ''];
for (const report of data.reports) {
 if (report.id === 'recommendation') {
  lines.push('## Recomendação temporal', '', `Clientes de validação: ${report.users}`, '', '| Modelo | Recall@10 | NDCG@10 |', '| --- | ---: | ---: |');
  for (const [name, metrics] of Object.entries(report.models)) {
   if (!Number.isFinite(metrics.recall) || !Number.isFinite(metrics.ndcg)) throw new Error('Invalid metric');
   lines.push(`| ${name} | ${metrics.recall.toFixed(6)} | ${metrics.ndcg.toFixed(6)} |`);
  }
 } else if (report.id === 'retrieval') {
  lines.push('', '## Recuperação experimental', '', `Produtos: ${report.products}. Consultas: ${report.queries}.`, '', 'Rótulos automáticos fracos, não julgamentos humanos. Não comparar estes números diretamente com recomendação.', '', '| Método | NDCG@10 — proxy |', '| --- | ---: |');
  for (const [name, groups] of Object.entries(report.models)) {
   if (!Number.isFinite(groups.all.ndcg)) throw new Error('Invalid retrieval metric');
   lines.push(`| ${name} | ${groups.all.ndcg.toFixed(6)} |`);
  }
 }
}
lines.push('', 'Limites: avaliação offline, sem comprovação de conversão, receita, disponibilidade ou preferência individual.', '');
return [{json: {report_id:'meal-evaluation-report-v1',schema_version:1,official_test_evaluated:false,reports:data.reports.length,markdown:lines.join('\n')}}];
